import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <cuda_pipeline.h>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int OcPerBlock = 4;
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 64;
  constexpr int PVec       = TILE_OW / (Threads / TILE_OH);
  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;
  const int col_tiles = (Wout + TILE_OW - 1) / TILE_OW;
  const int tile_idx  = blockIdx.x;
  const int tile_row  = tile_idx / col_tiles;
  const int tile_col  = tile_idx - tile_row * col_tiles;
  const int oh_base = tile_row * TILE_OH;
  const int ow_base = tile_col * TILE_OW;
  const int trow = tid / (TILE_OW / PVec);
  const int tcol = tid % (TILE_OW / PVec);
  const int ow_local0 = tcol * PVec;
  const int oh  = oh_base + trow;
  int ow[PVec];
  bool ow_valid[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    ow[i] = ow_base + ow_local0 + i;
    ow_valid[i] = (ow[i] < Wout);
  }
  const bool oh_valid  = (oh  < Hout);
  const int TILE_H_IN = (TILE_OH - 1) * stride_h + (Kh - 1) * dil_h + 1;
  const int TILE_W_IN = (TILE_OW - 1) * stride_w + (Kw - 1) * dil_w + 1;
  const int h_start = oh_base * stride_h - pad_h;
  const int w_start = ow_base * stride_w - pad_w;
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Shared memory: weights for OcPerBlock output channels + double-buffered staged input tile
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  const int per_oc_wsize = Cin * Kh * Kw;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, Cin, Kh, Kw),
      make_stride(per_oc_wsize, Kh * Kw, Kw, Int<1>{})
  );
  const int wsize = OcPerBlock * per_oc_wsize;
  const int tile_elems = TILE_H_IN * TILE_W_IN;
  T* sX_buf[2];
  sX_buf[0] = sW_ptr + wsize;
  sX_buf[1] = sX_buf[0] + tile_elems;
  for (int idx = tid; idx < wsize; idx += Threads) {
    int occ = idx / per_oc_wsize;
    int rem = idx - occ * per_oc_wsize;
    int oc = oc_base + occ;
    T val = T(0);
    if (oc < Cout) {
      val = W[(int64_t)oc * per_oc_wsize + rem];
    }
    sW_ptr[idx] = val;
  }
  constexpr int VecW = 16 / sizeof(T);
  const bool can_vectorize = (TILE_W_IN % VecW == 0);
  const int full_groups = TILE_W_IN / VecW;
  auto load_tile_async = [&](int ic, T* dst) {
    const T* base = X + (int64_t)n * sXn + (int64_t)ic * sXc;
    if (can_vectorize) {
      const int total_vec_groups = TILE_H_IN * full_groups;
      for (int idx = tid; idx < total_vec_groups; idx += Threads) {
        int rr = idx / full_groups;
        int gg = idx - rr * full_groups;
        int cc = gg * VecW;
        int ih = h_start + rr;
        int iw0 = w_start + cc;
        T* dstv = dst + rr * TILE_W_IN + cc;
        if ((unsigned)ih < (unsigned)H &&
            (unsigned)iw0 < (unsigned)Win &&
            (unsigned)(iw0 + VecW - 1) < (unsigned)Win) {
          const T* src = base + (int64_t)ih * sXh + (int64_t)iw0;
          __pipeline_memcpy_async(dstv, src, VecW * sizeof(T));
        } else {
          #pragma unroll
          for (int k = 0; k < VecW; ++k) {
            int iw = iw0 + k;
            if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
              const T* src = base + (int64_t)ih * sXh + (int64_t)iw;
              __pipeline_memcpy_async(dstv + k, src, sizeof(T));
            } else {
              dstv[k] = T(0);
            }
          }
        }
      }
    } else {
      for (int idx = tid; idx < tile_elems; idx += Threads) {
        int rr = idx / TILE_W_IN;
        int cc = idx - rr * TILE_W_IN;
        int ih = h_start + rr;
        int iw = w_start + cc;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          const T* src = base + (int64_t)ih * sXh + (int64_t)iw;
          __pipeline_memcpy_async(dst + idx, src, sizeof(T));
        } else {
          dst[idx] = T(0);
        }
      }
    }
  };
  if (Cin > 0) {
    load_tile_async(0, sX_buf[0]);
  }
  __pipeline_commit();
  __pipeline_wait_prior(0);
  __syncthreads();
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }
  for (int ic = 0; ic < Cin; ++ic) {
    T* cur = sX_buf[ic & 1];
    if (ic + 1 < Cin) {
      load_tile_async(ic + 1, sX_buf[(ic + 1) & 1]);
      __pipeline_commit();
    }
    #pragma unroll
    for (int kh = 0; kh < Kh; ++kh) {
      int local_h = trow * stride_h + kh * dil_h;
      const T* srow = cur + local_h * TILE_W_IN;
      #pragma unroll
      for (int kw = 0; kw < Kw; ++kw) {
        int local_w0 = ow_local0 * stride_w + kw * dil_w;
        float xval[PVec];
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          xval[i] = (float)srow[local_w0 + i * stride_w];
        }
        #pragma unroll
        for (int occ = 0; occ < OcPerBlock; ++occ) {
          float wval = (float)sW(occ, ic, kh, kw);
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            acc[occ][i] += xval[i] * wval;
          }
        }
      }
    }
    if (ic + 1 < Cin) {
      __pipeline_wait_prior(0);
      __syncthreads();
    }
  }
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    if (!oh_valid) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (ow_valid[i]) mY(oc, oh, ow[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t Kh   = w.size(2);
  int64_t Kw   = w.size(3);
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) / stride_h + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int Threads    = 128;
  constexpr int OcPerBlock = 4;
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 64;
  const int64_t row_tiles = (Hout + TILE_OH - 1) / TILE_OH;
  const int64_t col_tiles = (Wout + TILE_OW - 1) / TILE_OW;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(row_tiles * col_tiles),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );
  const int64_t TILE_H_IN = (TILE_OH - 1) * stride_h + (Kh - 1) * dil_h + 1;
  const int64_t TILE_W_IN = (TILE_OW - 1) * stride_w + (Kw - 1) * dil_w + 1;
  size_t smem_bytes = (size_t)OcPerBlock * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float)
                     + 2 * (size_t)TILE_H_IN * (size_t)TILE_W_IN * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }
  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      (int)Hout, (int)Wout
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
