  int ow[PVec];
  bool ow_valid[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    ow[i] = ow_base + ow_local0 + i;
    ow_valid[i] = (ow[i] < Wout);
  }
  const bool oh_valid  = (oh  < Hout);
  const int TILE_H_IN = (TILE_OH - 1) * stride_h + (Kh - 1) * dil_h + 1;
  const int TILE_W_IN = (TILE_OW - 1) * stride_w + (Kw - 1) * dil_w + 1;
  const int h_start = oh_base * stride_h - pad_h;
  const int w_start = ow_base * stride_w - pad_w;
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Shared memory: weights for OcPerBlock output channels + staged input tile for one ic
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  const int per_oc_wsize = Cin * Kh * Kw;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, Cin, Kh, Kw),
      make_stride(per_oc_wsize, Kh * Kw, Kw, Int<1>{})
  );
  const int wsize = OcPerBlock * per_oc_wsize;
  T* sX_ptr = sW_ptr + wsize;
  for (int idx = tid; idx < wsize; idx += Threads) {
    int occ = idx / per_oc_wsize;
    int rem = idx - occ * per_oc_wsize;
    int oc = oc_base + occ;
    T val = T(0);
    if (oc < Cout) {
      val = W[(int64_t)oc * per_oc_wsize + rem];
    }
    sW_ptr[idx] = val;
  }
  __syncthreads();
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }
  const int tile_elems = TILE_H_IN * TILE_W_IN;
  for (int ic = 0; ic < Cin; ++ic) {
    for (int idx = tid; idx < tile_elems; idx += Threads) {
      int rr = idx / TILE_W_IN;
      int cc = idx - rr * TILE_W_IN;
      int ih = h_start + rr;
      int iw = w_start + cc;
      float v = 0.0f;
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        v = (float)mX(ic, ih, iw);
      }
      sX_ptr[idx] = static_cast<T>(v);
    }
    __syncthreads();
    #pragma unroll
    for (int kh = 0; kh < Kh; ++kh) {
      int local_h = trow * stride_h + kh * dil_h;
      const T* srow = sX_ptr + local_h * TILE_W_IN;
      #pragma unroll
      for (int kw = 0; kw < Kw; ++kw) {
        int local_w0 = ow_local0 * stride_w + kw * dil_w;
        float xval[PVec];
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          xval[i] = (float)srow[local_w0 + i * stride_w];
        }
        #pragma unroll
        for (int occ = 0; occ < OcPerBlock; ++occ) {
          float wval = (float)sW(occ, ic, kh, kw);
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            acc[occ][i] += xval[i] * wval;
          }
        }
      }
    }
    __syncthreads();
  }
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    if (!oh_valid) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (ow_valid[i]) mY(oc, oh, ow[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}
