  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int Threads    = 128;
  constexpr int OcPerBlock = 4;
  constexpr int TILE_OH    = 8;
  constexpr int TILE_OW    = 64;
  const int64_t row_tiles = (Hout + TILE_OH - 1) / TILE_OH;
  const int64_t col_tiles = (Wout + TILE_OW - 1) / TILE_OW;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(row_tiles * col_tiles),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );
  const int64_t TILE_H_IN = (TILE_OH - 1) * stride_h + (Kh - 1) * dil_h + 1;
  const int64_t TILE_W_IN = (TILE_OW - 1) * stride_w + (Kw - 1) * dil_w + 1;
  size_t smem_bytes = (size_t)OcPerBlock * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float)
