class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input and asymmetric kernel,
    dilation and padding, implemented with a single custom CUDA kernel
    using CuTe tensors/layouts.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (int(kernel_size[0]), int(kernel_size[1]))

        if isinstance(stride, (tuple, list)):
            self.stride = (int(stride[0]), int(stride[1]))
        else:
            self.stride = (int(stride), int(stride))

        self.padding = (int(padding[0]), int(padding[1]))
        self.dilation = (int(dilation[0]), int(dilation[1]))

        Kh, Kw = self.kernel_size
        Cin = self.in_channels
        Cout = self.out_channels

        self.weight = nn.Parameter(torch.empty(Cout, Cin, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride[0]), int(self.stride[1]),
            int(self.padding[0]), int(self.padding[1]),
            int(self.dilation[0]), int(self.dilation[1]),
        )
